/**
 * @param {string} message diagnostic, without prefix or terminator
 * @returns {Error} a wrong-input failure
 */
function dataError(message) {
  const error = new Error(message);
  error.code = 'data';
  return error;
}

/**
 * Inner-join two tables on a column both headers carry.
 *
 * The output header is the left header followed by every right column except
 * the join column. One row is emitted per pair of a left row and a right row
 * whose join cells are equal as strings, left rows outermost and right rows
 * innermost, so a key repeated on both sides yields every pair.
 *
 * @param {{ header: string[], rows: string[][] }} left the left table
 * @param {{ header: string[], rows: string[][] }} right the right table
 * @param {string} column the join column, named in both headers
 * @returns {{ header: string[], rows: string[][] }} the joined table
 * @throws {Error} `data` when the column is missing from either header, or a
 *   carried right column repeats a left one
 */
export function join(left, right, column) {
  const leftKey = left.header.indexOf(column);
  const rightKey = right.header.indexOf(column);
  // Missing on either side is the same diagnostic; the left is asked first.
  if (leftKey === -1 || rightKey === -1) {
    throw dataError(`unknown column: ${column}`);
  }

  // Every right column but the join one is carried, and a carried name the
  // left header already holds would make the output header ambiguous.
  const carried = [];
  for (let index = 0; index < right.header.length; index += 1) {
    if (index === rightKey) continue;
    const name = right.header[index];
    if (left.header.includes(name)) {
      throw dataError(`duplicate column: ${name}`);
    }
    carried.push(index);
  }

  const header = [...left.header, ...carried.map((index) => right.header[index])];

  // Bucket the right rows by key, keeping file order inside each bucket, so
  // the pairs come out in the order the left-outermost walk requires.
  const buckets = new Map();
  for (const row of right.rows) {
    const key = row[rightKey];
    const bucket = buckets.get(key);
    if (bucket === undefined) buckets.set(key, [row]);
    else bucket.push(row);
  }

  const rows = [];
  for (const leftRow of left.rows) {
    const matches = buckets.get(leftRow[leftKey]);
    if (matches === undefined) continue;
    for (const rightRow of matches) {
      rows.push([...leftRow, ...carried.map((index) => rightRow[index])]);
    }
  }

  return { header, rows };
}
